/* Painted Gloucester offline worker. Generated by tools/build.mjs: edit tools/sw.template.js, not sw.js. */
const VERSION = '__VERSION__', SHELL_CACHE = 'pg-shell-' + VERSION, RUNTIME = 'pg-runtime', PAINTINGS = 'pg-paintings';
const SHELL = __SHELL__;
const scope = self.registration.scope, shellSet = new Set(SHELL.map(u => new URL(u, scope).href));

self.addEventListener('install', e => e.waitUntil((async () => {
  const c = await caches.open(SHELL_CACHE);
  await Promise.all(SHELL.map(u => c.add(new Request(u, { cache: 'reload' })).catch(() => {})));
  await self.skipWaiting();
})()));

self.addEventListener('activate', e => e.waitUntil((async () => {
  for (const k of await caches.keys()) if (k.startsWith('pg-shell-') && k !== SHELL_CACHE) await caches.delete(k);
  await self.clients.claim();
})()));

const fromCache = async req => (await caches.match(req, { ignoreSearch: true })) || null;
async function keep(req, res) { if (res && res.ok && res.status === 200) { const c = await caches.open(RUNTIME); c.put(req, res.clone()).catch(() => {}); } return res; }

self.addEventListener('fetch', e => {
  const req = e.request, url = new URL(req.url);
  if (req.method !== 'GET' || url.origin !== location.origin || req.headers.has('range')) return;   // street-map tiles, museums and video ranges go straight to the network
  if (url.pathname.endsWith('.pdf')) return;
  const clean = url.origin + url.pathname + (url.pathname.endsWith('/') ? 'index.html' : '');
  // the guide itself: always from the saved copy, so it opens with no signal and every file matches
  if (shellSet.has(clean)) { e.respondWith((async () => (await fromCache(clean)) || fetch(req))()); return; }
  // paintings and fonts never change once published: saved copy first
  if (/\/(img|thumbs|fonts|icons)\//.test(url.pathname)) { e.respondWith((async () => (await fromCache(req)) || keep(req, await fetch(req)))()); return; }
  // every other page (a painting's page, the brief): fresh when online, saved copy when not
  e.respondWith((async () => { try { return await keep(req, await fetch(req)); } catch (err) { const hit = await fromCache(req); if (hit) return hit; if (req.mode === 'navigate') {
      // no signal and this page was never opened: send a painting's or site's page to the same thing inside the saved guide
      const m = /\/works\/([a-z0-9-]+)\.html$/.exec(url.pathname);
      if (m) return Response.redirect(new URL('./#work-' + m[1], scope).href, 302);
      if (/\/sites\//.test(url.pathname)) return Response.redirect(new URL('./#map', scope).href, 302);
      return (await fromCache(new URL('index.html', scope).href)) || Response.error(); }
    throw err; } })());
});
